"""Server-rendered legal URLs, accessible to Meta without JavaScript or login."""
from html import escape
import os
from fastapi import APIRouter
from fastapi.responses import HTMLResponse
router=APIRouter()

def page(title,body):
    operator=escape(os.environ.get('LEGAL_OPERATOR_NAME','Identificação do operador pendente'))
    contact=escape(os.environ.get('LEGAL_CONTACT_EMAIL','Contato pendente'))
    pending=not(os.environ.get('LEGAL_OPERATOR_NAME') and os.environ.get('LEGAL_CONTACT_EMAIL'))
    notice='<p class="error-note">Documento pendente de identificação e revisão pelo operador antes da oferta pública.</p>' if pending else ''
    return HTMLResponse(f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · AUTO POSTS</title><link rel="stylesheet" href="/styles.css"></head><body><main class="public-page"><header class="public-header"><a class="brand" href="/">AUTO POSTS</a><nav><a href="/terms">Termos</a><a href="/privacy">Privacidade</a><a href="/data-deletion">Exclusão</a></nav></header><article class="panel profile-panel prose"><h1>{escape(title)}</h1><p>Operador: {operator}. Contato: {contact}.</p>{notice}{body}</article></main></body></html>''')

@router.get('/privacy',response_class=HTMLResponse)
def privacy():
    days=max(1,int(os.environ.get('MEDIA_RETENTION_DAYS','10')))
    return page('Política de privacidade',f'''<h2>Dados e finalidade</h2><p>Nome, e-mail, senha protegida por hash, sessões, campanhas, arquivos e histórico são tratados para autenticação, criação e publicação de conteúdo autorizado. A conexão Instagram usa tokens criptografados; a senha do Instagram não é solicitada.</p><h2>Fornecedores</h2><p>Backblaze B2 armazena mídia privada; a Meta realiza a publicação autorizada; Stripe pode processar assinaturas sem que este aplicativo armazene cartões. No modo IA, o briefing é enviado ao provedor configurado. O operador deve informar sua hospedagem, região, bases legais e transferências internacionais antes do lançamento.</p><h2>Cookies e retenção</h2><p>Cookies são usados para sessão e proteção CSRF. Mídia pode ser removida após {days} dias de inatividade, preservando trabalhos pendentes e materiais necessários a campanhas ativas. Cobranças e campanhas não são apagadas por essa política. Após exclusão da conta, registros legais de cobrança e uma representação hash do e-mail usado no teste podem permanecer para obrigações legais e prevenção de abuso, conforme política final do operador.</p><h2>Direitos</h2><p>O usuário pode editar o perfil e solicitar exclusão em Minha conta. Solicitações de acesso, correção, portabilidade ou exclusão adicional devem ser encaminhadas ao contato do operador. Consulte <a href="/data-deletion">as instruções de exclusão</a>. Prazos legais, retenção de backups e identificação do controlador devem ser revisados pelo operador.</p>''')

@router.get('/terms',response_class=HTMLResponse)
def terms():
    return page('Termos de uso','''<h2>Serviço e autorização</h2><p>O AUTO POSTS cria e agenda imagens e vídeos com informações fornecidas pelo cliente e IA opcional. Ao ativar uma campanha, o cliente autoriza as próximas gerações e publicações na conta profissional conectada, sem aprovação por post. É responsável pela exatidão do conteúdo e pelos direitos sobre imagens, marca e materiais enviados.</p><h2>Planos e cancelamento</h2><p>Os limites e valores aparecem no catálogo e no checkout. Não existe plano ilimitado. O Starter pode oferecer sete dias de teste uma vez por e-mail confirmado, com cartão. O pagamento é validado por webhook assinado; visitar uma página de sucesso não libera assinatura. Cancelamento e mudanças de plano ocorrem no portal de cobrança. O consumo de assinaturas ativas renova conforme o período confirmado pelo provedor.</p><h2>Limitações e encerramento</h2><p>Falhas de hospedagem ou provedores podem atrasar processamento e publicação. Não são garantidos alcance, engajamento ou resultado comercial. Pausar impede novos envios pendentes; publicação já enviada pode ser concluída pela Meta. O serviço não remove publicações já realizadas no Instagram ao limpar seus arquivos. O operador deve revisar condições contratuais, impostos, reembolsos, suporte e jurisdição antes de comercializar.</p>''')

@router.get('/data-deletion',response_class=HTMLResponse)
def deletion():
    return page('Excluir dados do AUTO POSTS','''<h2>Solicitar pelo painel</h2><ol><li>Entre na sua conta e acesse Minha conta.</li><li>Escolha Solicitar exclusão, confirme a senha e a intenção de encerrar.</li><li>O acesso será bloqueado; campanhas e filas pendentes serão interrompidas, e a assinatura será cancelada quando aplicável.</li><li>O processador removerá os arquivos e concluirá a exclusão após confirmação do armazenamento.</li></ol><p>Aguarde tarefas já em andamento antes de solicitar. Conteúdos já publicados no Instagram não são excluídos por este processo. Para revogar o acesso do aplicativo também na Meta, use as configurações de aplicativos/permissões do Instagram.</p><h2>Contato</h2><p>Sem acesso à conta, solicite atendimento ao contato do operador indicado acima. Pode ser necessária verificação de identidade. Registros legais de cobrança, controle de abuso e backups seguem a política final do operador, que deve informar seus prazos e fundamentos.</p>''')
